/**
 * Public multipart upload endpoint for applicants submitting CVs during job application. Accepts a single file via multipart/form-data. Allowed types: PDF, DOC, DOCX (max 10 MB). Authentication is NOT required — enables unauthenticated applicants to attach CVs.

 * @summary Upload a document file (CV, certificate, contract)
 */
export const UploadFileBody = zod.object({
  file: zod
    .instanceof(File)
    .describe("The file to upload (PDF, DOC, or DOCX, max 10 MB)"),
  jobId: zod
    .number()
    .describe(
      "ID of the job being applied to. Used to derive the owning agency for tenant-scoped ACL.",
    ),
});

export const UploadFileResponse = zod.object({
  url: zod
    .string()
    .describe(
      "Serving URL for the uploaded file via \/api\/storage\/objects\/\*",
    ),
  objectPath: zod.string().describe("Internal object path for reference"),
});

/**
 * Returns a GCS presigned PUT URL for direct client-to-GCS upload. Restricted to HR staff roles. After uploading, call POST /storage/uploads/confirm to apply tenant ACL so the file is retrievable via GET /storage/objects/*.

 * @summary Request a presigned URL for direct file upload (HR staff only)
 */

export const RequestUploadUrlBody = zod.object({
  name: zod.string().min(1),
  size: zod.number().min(1),
  contentType: zod.string().min(1),
});

export const RequestUploadUrlResponse = zod.object({
  uploadURL: zod.string().url(),
  objectPath: zod.string(),
});

/**
 * After uploading a file via the presigned URL returned by POST /storage/uploads/request-url, call this endpoint to apply the tenant ACL (sets the calling user's agency as the owner). Without this step, the file is not retrievable via GET /storage/objects/*. Restricted to HR staff roles.

 * @summary Apply tenant ACL to a staff-uploaded object
 */
export const ConfirmUploadBody = zod.object({
  objectPath: zod
    .string()
    .describe(
      "The objectPath returned by POST \/storage\/uploads\/request-url",
    ),
});

export const ConfirmUploadResponse = zod.object({
  objectPath: zod.string(),
  owner: zod.string().describe("The agencyId set as the ACL owner"),
});

/**
 * Returns the raw file content for private uploaded objects (CVs, contracts, certificates). Restricted to authenticated HR staff roles: admin, hr_officer, hiring_manager, executive. Applicants and unauthenticated users receive 401/403.

 * @summary Serve an uploaded object entity (HR staff only)
 */
export const GetStorageObjectParams = zod.object({
  objectPath: zod.coerce.string(),
});

